class Solution {
public:
    string kthSmallestPath(vector<int>& destination, int k) {
        int row = destination[0];
        int col = destination[1];
        int hLeft = col, vLeft = row;
        string result;
        int total = row + col;
        for (int i = 0; i < total; i++) {
            if (hLeft == 0) {
                result += 'V';
                vLeft--;
            } else if (vLeft == 0) {
                result += 'H';
                hLeft--;
            } else {
                long long c = comb(hLeft + vLeft - 1, vLeft);
                if ((long long)k <= c) {
                    result += 'H';
                    hLeft--;
                } else {
                    result += 'V';
                    k -= (int)c;
                    vLeft--;
                }
            }
        }
        return result;
    }
private:
    long long comb(int n, int r) {
        if (r < 0 || r > n) return 0;
        if (r > n - r) r = n - r;
        long long res = 1;
        for (int i = 0; i < r; i++) {
            res = res * (n - i) / (i + 1);
        }
        return res;
    }
};
